SELECT p.gender, p.age, h.admittime, h.dischtime, h.deathtime, d.diagnosis_code, d.diagnosis_name, l.labevent_id, l.value, l.valueuom, l.flag, l.priority, l.comments, row_number() OVER(PARTITION BY h.hadm_id ORDER BY l.labevent_id) AS lab_rank, COUNT(DISTINCT l.labevent_id) OVER(PARTITION BY h.hadm_id, l.value, l.valueuom, l.flag, l.priority, l.comments) AS lab_count, COUNT(DISTINCT l.labevent_id) OVER(PARTITION BY h.hadm_id) AS total_labs, (h.dischtime - h.admittime) AS length_of_stay, (SELECT COUNT(DISTINCT hadm_id) FROM admissions WHERE gender = 'M' AND age BETWEEN 40 AND 50 AND diagnosis_code = 'I60.9') AS total_male_patients, (SELECT COUNT(DISTINCT hadm_id) FROM admissions WHERE gender = 'M' AND age BETWEEN 40 AND 50 AND diagnosis_code = 'I60.9' AND (h.dischtime - h.admittime) > 72) AS male_patients_with_long_stay FROM patients p JOIN admissions h ON p.subject_id = h.subject_id JOIN diagnoses_icd d ON h.diagnosis_code = d.diagnosis_code LEFT JOIN labevents l ON h.hadm_id = l.subject_id AND l.charttime BETWEEN h.admittime AND h.dischtime WHERE p.gender = 'M' AND p.age BETWEEN 40 AND 50 AND d.diagnosis_code = 'I60.9' AND (h.dischtime - h.admittime) > 72 AND l.valueuom IN ('g/L', 'mg/dL', 'mmol/L') AND l.flag IN ('A', 'W', 'F') AND l.priority IN (1, 2, 3) AND l.comments IS NOT NULL;